-- Pidgeot Flight standalone wallet foundation. Apply to a NEW Supabase project.
-- All balances are integer coins. $1 deposit value maps to 10 coins.
create extension if not exists pgcrypto;
create table if not exists public.pidgeot_profiles(user_id uuid primary key references auth.users(id) on delete cascade,username text not null unique check(char_length(username) between 3 and 24),created_at timestamptz not null default now());
create table if not exists public.pidgeot_wallets(user_id uuid primary key references auth.users(id) on delete cascade,balance bigint not null default 5 check(balance>=0),updated_at timestamptz not null default now());
create table if not exists public.pidgeot_rounds(id uuid primary key default gen_random_uuid(),round_number bigint generated always as identity unique,status text not null default 'betting' check(status in ('betting','flying','crashed','settled')),betting_opens_at timestamptz not null default now(),starts_at timestamptz,crashed_at timestamptz,crash_multiplier numeric(12,4),server_seed_hash text not null,server_seed text,created_at timestamptz not null default now(),check(crash_multiplier is null or crash_multiplier>=1));
create table if not exists public.pidgeot_bets(id uuid primary key default gen_random_uuid(),round_id uuid not null references public.pidgeot_rounds(id),user_id uuid not null references auth.users(id) on delete cascade,amount bigint not null check(amount between 1 and 10000),auto_cashout numeric(12,4) check(auto_cashout is null or auto_cashout>=1.01),status text not null default 'active' check(status in ('active','cashed_out','lost','cancelled')),cashout_multiplier numeric(12,4),payout bigint not null default 0 check(payout>=0),placed_at timestamptz not null default now(),cashed_out_at timestamptz);
create table if not exists public.pidgeot_ledger(id bigint generated always as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,bet_id uuid references public.pidgeot_bets(id),kind text not null check(kind in ('free_credit','deposit_credit','bet_debit','cashout_credit','bet_refund','admin_test_credit')),amount bigint not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.pidgeot_deposits(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,network text not null default 'testnet',asset text not null,tx_hash text unique,usd_value numeric(12,2) not null check(usd_value>0),coin_amount bigint not null check(coin_amount>0),status text not null default 'pending' check(status in ('pending','confirmed','rejected')),created_at timestamptz not null default now(),confirmed_at timestamptz);
create index if not exists pidgeot_bets_round_idx on public.pidgeot_bets(round_id,status);create index if not exists pidgeot_bets_user_idx on public.pidgeot_bets(user_id,placed_at desc);create index if not exists pidgeot_ledger_user_idx on public.pidgeot_ledger(user_id,created_at desc);
alter table public.pidgeot_profiles enable row level security;alter table public.pidgeot_wallets enable row level security;alter table public.pidgeot_rounds enable row level security;alter table public.pidgeot_bets enable row level security;alter table public.pidgeot_ledger enable row level security;alter table public.pidgeot_deposits enable row level security;
drop policy if exists "profiles readable" on public.pidgeot_profiles;create policy "profiles readable" on public.pidgeot_profiles for select using(true);
drop policy if exists "profile self insert" on public.pidgeot_profiles;create policy "profile self insert" on public.pidgeot_profiles for insert with check(auth.uid()=user_id);
drop policy if exists "profile self update" on public.pidgeot_profiles;create policy "profile self update" on public.pidgeot_profiles for update using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "wallet self read" on public.pidgeot_wallets;create policy "wallet self read" on public.pidgeot_wallets for select using(auth.uid()=user_id);
drop policy if exists "rounds readable" on public.pidgeot_rounds;create policy "rounds readable" on public.pidgeot_rounds for select using(true);
drop policy if exists "bets self read" on public.pidgeot_bets;create policy "bets self read" on public.pidgeot_bets for select using(auth.uid()=user_id);
drop policy if exists "ledger self read" on public.pidgeot_ledger;create policy "ledger self read" on public.pidgeot_ledger for select using(auth.uid()=user_id);
drop policy if exists "deposits self read" on public.pidgeot_deposits;create policy "deposits self read" on public.pidgeot_deposits for select using(auth.uid()=user_id);
-- Intentionally no browser write policies for balances, bets, rounds, deposits, or ledger.
create or replace function public.pidgeot_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin
 insert into public.pidgeot_profiles(user_id,username) values(new.id,coalesce(nullif(split_part(new.email,'@',1),''),'pilot')||'_'||substr(new.id::text,1,5)) on conflict(user_id) do nothing;
 insert into public.pidgeot_wallets(user_id,balance) values(new.id,5) on conflict(user_id) do nothing;
 insert into public.pidgeot_ledger(user_id,kind,amount,metadata) values(new.id,'free_credit',5,'{"source":"new_user_free_play"}'::jsonb);
 return new;end $$;
drop trigger if exists on_pidgeot_user_created on auth.users;create trigger on_pidgeot_user_created after insert on auth.users for each row execute function public.pidgeot_new_user();
-- Realtime enabled separately in Supabase Dashboard after applying migration.
